// MAZGAL - ofis bolgesi duvar resimleri (canvas 2D, resim dosyasi yok)
// Her fonksiyon: (g, w, h, st) => void. st = olay durumu (ör. {extra:1}). Rastgelelik tohumlu: aynı resim her seferinde aynı çizilir.
(function () {
  function rng(seed) { let s = seed >>> 0; return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296); }
  const R = (r, a, b) => a + r() * (b - a);

  // --- ortak yardımcılar ---
  // kağıt: düz renk + leke + kenar kararması
  function paper(g, w, h, col, r) {
    g.fillStyle = col; g.fillRect(0, 0, w, h);
    for (let i = 0; i < 6; i++) {
      const x = R(r, 0, w), y = R(r, 0, h), rr = R(r, 20, 70);
      const gr = g.createRadialGradient(x, y, 0, x, y, rr);
      gr.addColorStop(0, "rgba(120,90,40,0.10)"); gr.addColorStop(1, "rgba(120,90,40,0)");
      g.fillStyle = gr; g.fillRect(x - rr, y - rr, rr * 2, rr * 2);
    }
    const e = g.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.35, w / 2, h / 2, Math.max(w, h) * 0.75);
    e.addColorStop(0, "rgba(60,40,10,0)"); e.addColorStop(1, "rgba(60,40,10,0.28)");
    g.fillStyle = e; g.fillRect(0, 0, w, h);
  }
  // fotokopi: gri gren, toner şeridi, koyu kenar
  function photocopy(g, w, h, r) {
    const img = g.getImageData(0, 0, w, h), d = img.data;
    for (let i = 0; i < d.length; i += 4) { const n = (r() - 0.5) * 34; d[i] += n; d[i + 1] += n; d[i + 2] += n; }
    g.putImageData(img, 0, 0);
    g.fillStyle = "rgba(0,0,0,0.10)"; g.fillRect(R(r, 40, w - 60), 0, R(r, 3, 9), h);   // toner şeridi
    g.strokeStyle = "rgba(20,20,20,0.55)"; g.lineWidth = 14; g.strokeRect(0, 0, w, h);    // kopya kenarı
    for (let i = 0; i < 300; i++) { g.fillStyle = "rgba(0,0,0,0.5)"; g.fillRect(R(r, 0, w), R(r, 0, h), 1.5, 1.5); }
  }
  // pastel boya çizgisi: üst üste kayık ince çizgiler
  function crayon(g, pts, col, width, r, close) {
    g.strokeStyle = col; g.lineCap = "round"; g.lineJoin = "round";
    for (let k = 0; k < 4; k++) {
      g.globalAlpha = 0.45; g.lineWidth = width * R(r, 0.6, 1.1);
      g.beginPath();
      pts.forEach(([x, y], i) => { const px = x + R(r, -2, 2), py = y + R(r, -2, 2); i ? g.lineTo(px, py) : g.moveTo(px, py); });
      if (close) g.closePath(); g.stroke();
    }
    g.globalAlpha = 1;
  }
  function crayonFill(g, x, y, w, h, col, r, dens = 1) {   // zikzak dolgu
    g.strokeStyle = col; g.lineWidth = 3; g.globalAlpha = 0.5; g.beginPath();
    for (let i = 0; i < h * dens / 3; i++) { const yy = y + i * 3 / dens; g.moveTo(x + R(r, -3, 3), yy); g.lineTo(x + w + R(r, -3, 3), yy + R(r, -2, 2)); }
    g.stroke(); g.globalAlpha = 1;
  }
  function circle(g, x, y, rad) { g.beginPath(); g.arc(x, y, rad, 0, Math.PI * 2); }
  function stick(g, x, y, s, col, r, vest) {   // çöp adam, y = ayak hizası, s = boy
    const head = s * 0.13;
    crayon(g, [[x, y - s + head * 2], [x, y - s * 0.4]], col, 4, r);
    crayon(g, [[x - s * 0.18, y], [x, y - s * 0.4], [x + s * 0.18, y]], col, 4, r);
    crayon(g, [[x - s * 0.25, y - s * 0.6], [x, y - s * 0.72], [x + s * 0.25, y - s * 0.6]], col, 4, r);
    g.lineWidth = 3; g.strokeStyle = col; circle(g, x, y - s + head, head); g.stroke();
    if (vest) { crayonFill(g, x - s * 0.1, y - s * 0.75, s * 0.2, s * 0.3, "#f07a1a", r, 1.5); crayon(g, [[x - head * 1.2, y - s + head * 0.4], [x + head * 1.2, y - s + head * 0.4]], "#e8c51a", 6, r); }
  }
  function typed(g, txt, x, y, size, col = "#1b1b1b", bold = false, align = "left") {
    g.font = `${bold ? "bold " : ""}${size}px "Courier New", monospace`; g.fillStyle = col; g.textAlign = align; g.textBaseline = "alphabetic"; g.fillText(txt, x, y);
  }
  function hand(g, txt, x, y, size, col, r, rot = 0, align = "left") {   // el yazısı: eğik, titrek
    g.save(); g.translate(x, y); g.rotate(rot + R(r, -0.02, 0.02));
    g.font = `italic ${size}px "Comic Sans MS", "Segoe Print", cursive`; g.fillStyle = col; g.textAlign = align;
    g.globalAlpha = 0.85; g.fillText(txt, 0, 0); g.globalAlpha = 0.35; g.fillText(txt, 0.8, 0.6); g.restore(); g.globalAlpha = 1;
  }
  function tape(g, x, y, w, h, rot) {   // köşe bandı
    g.save(); g.translate(x, y); g.rotate(rot); g.fillStyle = "rgba(235,228,190,0.75)"; g.fillRect(-w / 2, -h / 2, w, h); g.restore();
  }

  const P = {};

  // P01 MAZGAL (çocuk resmi) 512x512. st.men = kuyudaki adam sayısı (varsayılan 6)
  P.p01_mazgal = (g, w, h, st = {}) => {
    const r = rng(101); paper(g, w, h, "#f2ecdc", r);
    crayon(g, [[60, 70], [60, 70]], "#f2c21a", 1, r);
    g.fillStyle = "rgba(240,190,20,0.55)"; circle(g, 70, 70, 38); g.fill();                          // güneş
    for (let a = 0; a < 12; a++) { const t = a / 12 * 6.28; crayon(g, [[70 + Math.cos(t) * 46, 70 + Math.sin(t) * 46], [70 + Math.cos(t) * 66, 70 + Math.sin(t) * 66]], "#e6a811", 4, r); }
    crayonFill(g, 0, 250, 512, 40, "#6b6b6b", r);                                                     // yol
    crayon(g, [[0, 250], [512, 250]], "#333", 4, r); crayon(g, [[0, 290], [512, 290]], "#333", 4, r);
    crayonFill(g, 0, 290, 512, 222, "#4a3626", r, 0.9);                                               // toprak altı
    g.fillStyle = "#111"; g.beginPath(); g.ellipse(300, 270, 52, 16, 0, 0, 6.28); g.fill();            // mazgal ağzı
    crayon(g, [[248, 270], [248, 500]], "#111", 6, r); crayon(g, [[352, 270], [352, 500]], "#111", 6, r);   // kuyu
    crayonFill(g, 252, 290, 96, 210, "#151515", r, 1.2);
    crayon(g, [[180, 248], [215, 205], [250, 248]], "#ff7a00", 5, r, true);                          // devrik koni
    const n = st.men ?? 6;
    for (let i = 0; i < n; i++) stick(g, 300 + (i % 2 ? 18 : -18), 330 + i * 30, 26, "#ddd", r, true); // kuyudaki adamlar (beyaz)
    stick(g, 120, 245, 90, "#1a1a1a", r, false); hand(g, "BEN", 92, 140, 22, "#1a1a1a", r);           // çocuk
    stick(g, 420, 245, 70, "#1a1a1a", r, false);
    hand(g, "AMCALAR AŞAĞIDA ÇALIŞIYO", 150, 60, 24, "#c0201a", r, -0.03);
    hand(g, "sabah okula giderken", 180, 100, 17, "#3050a0", r);
  };

  // P02 KAT PLANI 512x768 (mavi plan). Uymayan plan: ortada kulübe ve mazgal, çıkış panonun arkasında
  P.p02_plan = (g, w, h, st = {}) => {
    const r = rng(202); g.fillStyle = "#1d3f73"; g.fillRect(0, 0, w, h);
    g.strokeStyle = "rgba(220,230,245,0.12)"; g.lineWidth = 1;
    for (let x = 0; x < w; x += 16) { g.beginPath(); g.moveTo(x, 0); g.lineTo(x, h); g.stroke(); }
    for (let y = 0; y < h; y += 16) { g.beginPath(); g.moveTo(0, y); g.lineTo(w, y); g.stroke(); }
    g.strokeStyle = "#e6ecf5"; g.lineWidth = 4; g.strokeRect(32, 80, 448, 600);
    const room = (x, y, ww, hh, label) => { g.lineWidth = 3; g.strokeRect(x, y, ww, hh); typed(g, label, x + ww / 2, y + hh / 2 + 6, 15, "#e6ecf5", true, "center"); };
    room(32, 80, 224, 160, "BEKLEME"); room(256, 80, 224, 160, "İHBAR HATTI");
    room(32, 520, 224, 160, "ARŞİV"); room(256, 520, 224, 160, "NÖBET ODASI");
    room(176, 300, 160, 140, "");                                                                 // ortada olmaması gereken oda
    typed(g, "FEN İŞLERİ", 256, 360, 14, "#e6ecf5", true, "center"); typed(g, "KULÜBESİ", 256, 378, 14, "#e6ecf5", true, "center");
    g.lineWidth = 2; circle(g, 256, 410, 14); g.stroke();                                         // mazgal
    for (let i = -10; i <= 10; i += 5) { g.beginPath(); g.moveTo(246, 410 + i); g.lineTo(266, 410 + i); g.stroke(); }
    // kapı boşlukları (yay)
    for (const [x, y] of [[140, 240], [370, 240], [140, 520], [370, 520]]) { g.fillStyle = "#1d3f73"; g.fillRect(x - 20, y - 3, 40, 6); g.beginPath(); g.arc(x - 20, y, 40, -1.2, 0); g.stroke(); }
    // pano + arkasında çıkış
    g.fillStyle = "#e6ecf5"; g.fillRect(440, 600, 24, 40); typed(g, "PANO", 452, 660, 11, "#e6ecf5", true, "center");
    g.save(); g.setLineDash([6, 5]); g.strokeRect(464, 590, 36, 60); g.restore();
    typed(g, "ÇIKIŞ?", 482, 584, 11, "#ffd34a", true, "center");
    // başlık
    typed(g, "FEN İŞLERİ MÜDÜRLÜĞÜ · İHBAR BÜROSU", 32, 40, 15, "#e6ecf5", true);
    typed(g, "KAT: -1   ÖLÇEK: 1/—   TARİH: 14.10", 32, 62, 12, "#c9d4e6");
    // BURADASINIZ: st.here = [x,y] olaylarla değişir; varsayılan nöbet odası
    const [hx, hy] = st.here || [380, 600];
    g.strokeStyle = "#e0332a"; g.lineWidth = 5; g.beginPath(); g.moveTo(hx - 12, hy - 12); g.lineTo(hx + 12, hy + 12); g.moveTo(hx + 12, hy - 12); g.lineTo(hx - 12, hy + 12); g.stroke();
    typed(g, "BURADASINIZ", hx, hy + 30, 12, "#ffb0a8", true, "center");
    if (st.second) { const [sx, sy] = st.second; g.strokeStyle = "rgba(224,51,42,0.75)"; g.lineWidth = 3; g.beginPath(); g.moveTo(sx - 9, sy - 9); g.lineTo(sx + 9, sy + 9); g.moveTo(sx + 9, sy - 9); g.lineTo(sx - 9, sy + 9); g.stroke(); }
    typed(g, "ONAY: ________   PAFTA 1/1", 32, 720, 12, "#c9d4e6");
  };

  // P03 İHBAR KAYIT FORMU (fotokopi) 512x768
  P.p03_form = (g, w, h, st = {}) => {
    const r = rng(303); g.fillStyle = "#e9e9e4"; g.fillRect(0, 0, w, h);
    g.save(); g.translate(w / 2, h / 2); g.rotate(-0.025); g.translate(-w / 2, -h / 2);
    typed(g, "T.C.", 256, 50, 14, "#1b1b1b", true, "center");
    typed(g, "FEN İŞLERİ MÜDÜRLÜĞÜ", 256, 70, 16, "#1b1b1b", true, "center");
    typed(g, "GECE İHBAR KAYIT FORMU", 256, 96, 18, "#1b1b1b", true, "center");
    typed(g, "Form No: 00/00     Saat sütunu doldurulmaz.", 40, 124, 11);
    const cols = [40, 140, 250, 360, 472], heads = ["TARİH", "İHBAR EDEN", "GÖNDERİLEN", "SONUÇ"];
    g.strokeStyle = "#1b1b1b"; g.lineWidth = 1.5;
    const top = 140, rh = 52, rows = 8;
    for (let i = 0; i <= rows; i++) { g.beginPath(); g.moveTo(40, top + i * rh); g.lineTo(472, top + i * rh); g.stroke(); }
    cols.forEach((x) => { g.beginPath(); g.moveTo(x, top); g.lineTo(x, top + rows * rh); g.stroke(); });
    heads.forEach((t, i) => typed(g, t, (cols[i] + cols[i + 1]) / 2, top + 32, 12, "#1b1b1b", true, "center"));
    const data = [
      ["06.03.2016", "—", "HALİL", "DÖNMEDİ"],
      ["03.02.2019", "HALİL", "MEHMET", "DÖNMEDİ"],
      ["17.08.2021", "MEHMET", "AYŞE", "DÖNMEDİ"],
      ["29.11.2023", "AYŞE", "KENAN", "DÖNMEDİ"],
      ["22.06.2024", "KENAN", "ZEYNEP", "DÖNMEDİ"],
      ["14.10.2026", "ZEYNEP", "SELİM", ""],
    ];
    data.forEach((row, i) => row.forEach((t, j) => typed(g, t, (cols[j] + cols[j + 1]) / 2, top + (i + 1) * rh + 32, 13, "#1b1b1b", false, "center")));
    // son satır: kurşun kalemle önceden doldurulmuş
    hand(g, st.filled === false ? "" : "SELİM", (cols[1] + cols[2]) / 2, top + 7 * rh + 34, 20, "#4a4a55", r, -0.04, "center");
    hand(g, "?", (cols[2] + cols[3]) / 2, top + 7 * rh + 34, 22, "#4a4a55", r, 0, "center");
    typed(g, "Not: İhbar metninin dışına çıkılmaz.", 40, 590, 12);
    typed(g, "\"Köşedeki mazgalın kapağı açık kalmış.\"", 40, 612, 12);
    typed(g, "Nöbetçi telefonu açtıktan sonra formu imzalar.", 40, 646, 12);
    typed(g, "İMZA: ...........................", 40, 700, 13);
    g.restore();
    photocopy(g, w, h, r);
  };

  // P04 TAKVİM 512x768: koparılmış yapraklar, hepsi 14 EKİM
  P.p04_takvim = (g, w, h, st = {}) => {
    const r = rng(404); g.fillStyle = "#c9b98a"; g.fillRect(0, 0, w, h);   // karton arka
    g.fillStyle = "#8a1d1a"; g.fillRect(96, 60, 320, 60);
    typed(g, "FEN İŞLERİ · 2026", 256, 100, 22, "#f2e8d0", true, "center");
    // yırtık yaprak kalıntıları
    for (let i = 0; i < 9; i++) { g.fillStyle = "#efe9da"; g.beginPath(); g.moveTo(96, 120 + i * 2); for (let x = 96; x <= 416; x += 10) g.lineTo(x, 124 + i * 2 + R(r, 0, 8)); g.lineTo(416, 120 + i * 2); g.fill(); }
    g.fillStyle = "#f6f2e6"; g.fillRect(96, 140, 320, 420);
    typed(g, "EKİM", 256, 200, 40, "#8a1d1a", true, "center");
    typed(g, "14", 256, 400, 190, "#1b1b1b", true, "center");
    typed(g, "ÇARŞAMBA", 256, 460, 30, "#1b1b1b", true, "center");
    typed(g, "Kasım 14 gün sonra", 256, 520, 13, "#6a6a6a", false, "center");
    // alttaki kopmamış yaprakların kenarları da 14
    for (let i = 1; i <= 3; i++) { g.fillStyle = `rgb(${240 - i * 10},${236 - i * 10},${222 - i * 10})`; g.fillRect(96 + i * 4, 560 + i * 8, 320, 8); }
    hand(g, "14", 400, 600, 20, "#8a1d1a", r); hand(g, "14", 380, 612, 16, "#8a1d1a", r); hand(g, "14", 360, 622, 14, "#8a1d1a", r);
    g.strokeStyle = "#c0201a"; g.lineWidth = 5; g.beginPath(); g.ellipse(256, 340, 120, 100, 0.05, 0, 6.28); g.stroke();   // daire
    hand(g, "yine", 330, 250, 26, "#c0201a", r, 0.2);
  };

  // P05 ÇENTİKLER 512x512: tarih başlıklı 6 sütun, son sütunun başlığı yok
  P.p05_cetik = (g, w, h, st = {}) => {
    const r = rng(505);   // şeffaf: duvar dokusunun üstüne decal
    const heads = ["2016", "2019", "2021", "2023", "2024", ""];
    const counts = [41, 12, 23, 9, 9 + 0, 3 + (st.extra || 0)];
    heads.forEach((hd, c) => {
      const x0 = 20 + c * 82;
      hand(g, hd, x0 + 4, 40, 22, "#3a2a1a", r);
      for (let i = 0; i < counts[c]; i++) {
        const grp = Math.floor(i / 5), k = i % 5, y = 60 + Math.floor(grp / 2) * 70, x = x0 + (grp % 2) * 38;
        g.strokeStyle = "rgba(50,35,25,0.8)"; g.lineWidth = 2.5;
        g.beginPath();
        if (k < 4) { g.moveTo(x + k * 7 + R(r, -1, 1), y); g.lineTo(x + k * 7 + R(r, -2, 2), y + 50); }
        else { g.moveTo(x - 4, y + 40); g.lineTo(x + 28, y + 8); }
        g.stroke();
      }
    });
  };

  // P06 EL İZLERİ 512x768: hep sol el, giderek yukarı; en üstteki uzanılamayacak yerde
  P.p06_eller = (g, w, h, st = {}) => {
    const r = rng(606);   // şeffaf decal
    const palm = (x, y, s, a, col) => {
      g.save(); g.translate(x, y); g.rotate(a); g.scale(s, s); g.fillStyle = col;
      g.beginPath(); g.ellipse(0, 0, 34, 40, 0, 0, 6.28); g.fill();                     // avuç
      const f = [[-30, -40, 9, 30, -0.35], [-12, -62, 8, 34, -0.08], [6, -66, 8, 36, 0.02], [22, -58, 8, 32, 0.15], [40, -6, 9, 26, 1.0]];  // sol el: başparmak sağda
      f.forEach(([fx, fy, rx, ry, fa]) => { g.beginPath(); g.ellipse(fx, fy, rx, ry, fa, 0, 6.28); g.fill(); });
      g.restore();
    };
    for (let i = 0; i < 7; i++) {
      const y = 700 - i * 95 + R(r, -10, 10), x = 256 + R(r, -120, 120);
      palm(x, y, R(r, 0.8, 0.95), R(r, -0.4, 0.4), `rgba(70,55,40,${0.30 + i * 0.05})`);
    }
    hand(g, "TAVAN VARDI", 150, 40, 22, "rgba(60,45,30,0.9)", r, 0.02);
  };

  // P07 ELLE ÇİZİLMİŞ HARİTA 512x512: kareli kâğıt. maze verilirse oyunun labirentini AYNA çevirip çizer
  P.p07_harita = (g, w, h, st = {}) => {
    const r = rng(707); paper(g, w, h, "#f4f1e6", r);
    g.strokeStyle = "rgba(80,110,170,0.25)"; g.lineWidth = 1;
    for (let x = 0; x < w; x += 16) { g.beginPath(); g.moveTo(x, 0); g.lineTo(x, h); g.stroke(); }
    for (let y = 0; y < h; y += 16) { g.beginPath(); g.moveTo(0, y); g.lineTo(w, y); g.stroke(); }
    const m = st.maze; // m: 2B dizi, 1 = duvar
    g.strokeStyle = "rgba(55,55,65,0.85)"; g.lineWidth = 2;
    if (m) {
      const H = m.length, W = m[0].length, cs = Math.min(440 / W, 400 / H), ox = 36, oy = 70;
      for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) if (m[y][x]) { const mx = W - 1 - x; g.strokeRect(ox + mx * cs + R(r, -1, 1), oy + y * cs + R(r, -1, 1), cs, cs); }
    } else {
      const ox = 40, oy = 70, cs = 24; let cx = 8, cy = 8; g.beginPath(); g.moveTo(ox + cx * cs, oy + cy * cs);
      for (let i = 0; i < 70; i++) { const d = Math.floor(r() * 4); cx = Math.max(0, Math.min(17, cx + [1, -1, 0, 0][d])); cy = Math.max(0, Math.min(16, cy + [0, 0, 1, -1][d])); g.lineTo(ox + cx * cs, oy + cy * cs); }
      g.stroke();
    }
    hand(g, "X uyandım", 300, 120, 18, "#3a3a48", r); hand(g, "kaset?", 90, 300, 16, "#3a3a48", r); hand(g, "PANO ←", 330, 430, 18, "#3a3a48", r);
    hand(g, "BU HARİTA YANLIŞ. TERS ÇİZMİŞİM.", 30, 40, 18, "#a01a1a", r, -0.02);
    hand(g, "ya da koridor ters", 260, 495, 15, "#a01a1a", r, 0.01);
  };

  // P08 YAPILACAKLAR LİSTESİ 512x768 (çizgili defter yaprağı)
  P.p08_liste = (g, w, h, st = {}) => {
    const r = rng(808); paper(g, w, h, "#f3efe2", r);
    g.strokeStyle = "rgba(60,80,140,0.35)"; g.lineWidth = 1;
    for (let y = 110; y < h - 20; y += 44) { g.beginPath(); g.moveTo(20, y); g.lineTo(w - 20, y); g.stroke(); }
    g.strokeStyle = "rgba(190,40,40,0.5)"; g.beginPath(); g.moveTo(70, 0); g.lineTo(70, h); g.stroke();
    hand(g, "YAPILACAKLAR", 90, 80, 30, "#20253a", r);
    const items = ["Kapağı kapat", "Feneri yak", "Eğil, dinle", "Düş", "Uyan", "Kasetleri dinle", "Panoyu bul", "Telefonu AÇMA", "Kapağı kapat"];
    items.forEach((t, i) => {
      const y = 100 + (i + 1) * 44 - 8; hand(g, `${i + 1}. ${t}`, 82, y, 24, "#20253a", r);
      if (i < 5) crayon(g, [[440, y - 10], [452, y], [476, y - 26]], "#1a6a2a", 3, r);          // tikler
    });
    crayon(g, [[300, 100 + 9 * 44 - 18], [480, 100 + 9 * 44 - 30], [490, 140], [300, 128]], "#20253a", 2, r);   // 9'dan 1'e geri ok
    crayon(g, [[300, 128], [314, 120], [300, 128], [312, 138]], "#20253a", 2, r);
  };

  // P09 NÖBET ÇİZELGESİ 512x512 (daktilo tablo)
  P.p09_nobet = (g, w, h, st = {}) => {
    const r = rng(909); g.fillStyle = "#ecebe4"; g.fillRect(0, 0, w, h);
    typed(g, "GECE NÖBET ÇİZELGESİ", 256, 50, 20, "#1b1b1b", true, "center");
    const days = ["PZT", "SAL", "ÇAR", "PER", "CUM", "CMT", "PAZ"];
    g.strokeStyle = "#1b1b1b"; g.lineWidth = 1.5;
    for (let i = 0; i <= 8; i++) { g.beginPath(); g.moveTo(40, 80 + i * 46); g.lineTo(472, 80 + i * 46); g.stroke(); }
    [40, 130, 260, 360, 472].forEach((x) => { g.beginPath(); g.moveTo(x, 80); g.lineTo(x, 448); g.stroke(); });
    ["GÜN", "TARİH", "SAAT", "NÖBETÇİ"].forEach((t, i) => typed(g, t, [85, 195, 310, 416][i], 110, 13, "#1b1b1b", true, "center"));
    days.forEach((d, i) => {
      const y = 80 + (i + 1) * 46 + 30;
      typed(g, d, 85, y, 14, "#1b1b1b", false, "center"); typed(g, "14.10", 195, y, 14, "#1b1b1b", false, "center");
      typed(g, "00:00", 310, y, 14, "#1b1b1b", false, "center"); typed(g, i === 2 ? "HALİL" : "SELİM", 416, y, 14, "#1b1b1b", false, "center");
    });
    g.strokeStyle = "#2a2a6a"; g.lineWidth = 3; g.beginPath(); g.moveTo(380, 80 + 3 * 46 + 25); g.lineTo(452, 80 + 3 * 46 + 18); g.stroke();   // Halil üstü çizik
    hand(g, "Selim", 440, 80 + 3 * 46 + 14, 15, "#2a2a6a", r, -0.1);
    typed(g, "Değişiklik yapılamaz.", 40, 480, 12);
    photocopy(g, w, h, r);
  };

  // P10 HEPİMİZ (çocuk resmi, el ele çöp adamlar) 512x512. st.filled: 7. figür dolu mu
  P.p10_hepimiz = (g, w, h, st = {}) => {
    const r = rng(1010); paper(g, w, h, "#f4efe0", r);
    crayonFill(g, 0, 420, 512, 92, "#5a9a3a", r);                                                // çimen
    const names = ["H", "M", "A", "K", "Z", "S"]; const cols = ["#2a50a0", "#a02a2a", "#a03a90", "#2a8a6a", "#c08a1a", "#f07a1a"];
    const n = 6 + (st.filled ? 1 : 0);
    for (let i = 0; i < 7; i++) {
      const x = 50 + i * 68, y = 410;
      if (i < n) { stick(g, x, y, 130, cols[i] || "#555", r, i === 5 || i === 6); hand(g, names[i] || "", x - 6, 450, 26, "#1a1a1a", r); }
      else { g.save(); g.setLineDash([6, 8]); g.strokeStyle = "rgba(40,40,40,0.6)"; g.lineWidth = 2; g.strokeRect(x - 26, y - 130, 52, 130); g.restore(); hand(g, "?", x - 6, 360, 30, "#555", r); }
      if (i > 0 && i < n) crayon(g, [[x - 68 + 17, y - 78], [x - 17, y - 78]], "#1a1a1a", 3, r);  // el ele
    }
    hand(g, "HEPİMİZ", 170, 80, 46, "#c0201a", r, -0.03);
    g.fillStyle = "rgba(240,190,20,0.0)";
  };

  // P11 BEYAZ TAHTA ŞEMASI 768x512 (yatay): döngü diyagramı
  P.p11_tahta = (g, w, h, st = {}) => {
    const r = rng(1111); g.fillStyle = "#e9ecec"; g.fillRect(0, 0, w, h);
    g.strokeStyle = "#9aa3a8"; g.lineWidth = 10; g.strokeRect(5, 5, w - 10, h - 10);
    for (let i = 0; i < 5; i++) { g.fillStyle = "rgba(60,80,90,0.06)"; g.fillRect(R(r, 0, w - 200), R(r, 0, h - 80), R(r, 120, 260), R(r, 30, 80)); }   // silinti
    const cx = 384, cy = 270, rad = 170;
    const nodes = ["TELEFON", "MAZGAL", "KORİDOR", "KASET", "PANO", "TELEFON?"];
    g.strokeStyle = "#1a3a8a"; g.lineWidth = 3;
    nodes.forEach((t, i) => {
      const a = -Math.PI / 2 + i / nodes.length * 6.28, x = cx + Math.cos(a) * rad * 1.3, y = cy + Math.sin(a) * rad * 0.85;
      g.strokeStyle = i === 5 ? "#b01a1a" : "#1a3a8a"; g.strokeRect(x - 62, y - 20, 124, 40);
      typed(g, t, x, y + 7, 18, i === 5 ? "#b01a1a" : "#1a3a8a", true, "center");
      const a2 = -Math.PI / 2 + (i + 0.5) / nodes.length * 6.28, ax = cx + Math.cos(a2) * rad * 1.15, ay = cy + Math.sin(a2) * rad * 0.75;
      g.strokeStyle = "#1a3a8a"; g.beginPath(); g.arc(ax, ay, 5, 0, 6.28); g.stroke();
    });
    typed(g, "AÇAN ARAR", cx, cy - 4, 26, "#b01a1a", true, "center");
    typed(g, "açmayan ?", cx, cy + 26, 16, "#1a3a8a", false, "center");
    typed(g, "SALI TOPLANTI: İPTAL", 30, 40, 14, "#2a7a3a");
  };

  // P12 KARALAMA 512x512: koyu spiral yığın, ortada temiz dikdörtgen "PANO"
  P.p12_karalama = (g, w, h, st = {}) => {
    const r = rng(1212); paper(g, w, h, "#efeadb", r);
    g.strokeStyle = "rgba(20,20,25,0.55)"; g.lineWidth = 2;
    for (let k = 0; k < 900; k++) {
      const a = R(r, 0, 6.28), d = R(r, 60, 230);
      g.beginPath(); g.arc(256 + Math.cos(a) * d * 0.3, 256 + Math.sin(a) * d * 0.3, d * R(r, 0.5, 0.9), a, a + R(r, 0.5, 2)); g.stroke();
    }
    g.fillStyle = "#efeadb"; g.fillRect(206, 216, 100, 80); g.strokeStyle = "#111"; g.lineWidth = 3; g.strokeRect(206, 216, 100, 80);
    typed(g, "PANO", 256, 262, 22, "#111", true, "center");
    g.save(); g.setLineDash([4, 4]); g.strokeRect(222, 300, 68, 30); g.restore(); typed(g, "arkası", 256, 320, 12, "#111", false, "center");
  };

  // P13 PENCERE KAĞIDI 512x768: camın üstüne yapıştırılmış "dışarısı": yağmurlu gece sokağı, lamba, kamyonet, açık mazgal
  P.p13_pencere = (g, w, h, st = {}) => {
    const r = rng(1313); const sky = g.createLinearGradient(0, 0, 0, h); sky.addColorStop(0, "#0d1220"); sky.addColorStop(1, "#1c1f26");
    g.fillStyle = sky; g.fillRect(0, 0, w, h);
    g.fillStyle = "#2a2c30"; g.fillRect(0, 560, w, 208);                                           // asfalt
    g.fillStyle = "#4a4c50"; g.fillRect(0, 540, w, 20);                                            // kaldırım
    g.strokeStyle = "#555"; g.lineWidth = 8; g.beginPath(); g.moveTo(400, 545); g.lineTo(400, 180); g.lineTo(350, 170); g.stroke();   // lamba direği
    const on = st.lampOn !== false;
    if (on) { const gl = g.createRadialGradient(345, 185, 0, 345, 185, 220); gl.addColorStop(0, "rgba(255,190,90,0.6)"); gl.addColorStop(1, "rgba(255,190,90,0)"); g.fillStyle = gl; g.fillRect(100, 0, 412, 600); }
    g.fillStyle = on ? "#ffd98a" : "#333"; g.fillRect(332, 172, 28, 10);
    // kamyonet
    g.fillStyle = "#d4d6d6"; g.fillRect(40, 470, 200, 70); g.fillRect(170, 430, 80, 60); g.fillStyle = "#1a2a3a"; g.fillRect(185, 440, 50, 30);
    g.fillStyle = "#111"; circle(g, 80, 545, 20); g.fill(); circle(g, 200, 545, 20); g.fill();
    g.fillStyle = "#1d3f73"; g.fillRect(60, 490, 90, 22); typed(g, "FEN İŞLERİ", 105, 506, 11, "#e8ecf2", true, "center");
    // mazgal ve koni
    g.fillStyle = "#050505"; g.beginPath(); g.ellipse(320, 640, 60, 16, 0, 0, 6.28); g.fill();
    g.fillStyle = "#e8601a"; g.beginPath(); g.moveTo(410, 650); g.lineTo(450, 630); g.lineTo(455, 660); g.fill();
    g.strokeStyle = "rgba(180,200,230,0.25)"; g.lineWidth = 1;                                       // yağmur
    for (let i = 0; i < 260; i++) { const x = R(r, 0, w), y = R(r, 0, h); g.beginPath(); g.moveTo(x, y); g.lineTo(x - 4, y + 18); g.stroke(); }
    hand(g, "DIŞARISI", 20, 50, 30, "rgba(240,230,200,0.85)", r);
    hand(g, "(böyleydi)", 40, 84, 18, "rgba(240,230,200,0.7)", r);
    tape(g, 30, 10, 80, 22, -0.3); tape(g, 480, 10, 80, 22, 0.4); tape(g, 30, 755, 80, 22, 0.3); tape(g, 480, 755, 80, 22, -0.2);
  };

  // P14 KAYIP İLANI 512x768 (fotokopi). st.name / st.date ile ikinci kopya: SELİM 14.10.2026
  P.p14_kayip = (g, w, h, st = {}) => {
    const r = rng(1414 + (st.name ? 7 : 0)); g.fillStyle = "#f0f0ec"; g.fillRect(0, 0, w, h);
    typed(g, "KAYIP", 256, 110, 96, "#111", true, "center");
    g.fillStyle = "#9a9a9a"; g.fillRect(136, 150, 240, 280);
    g.strokeStyle = "#555"; g.lineWidth = 2; g.beginPath(); g.moveTo(136, 150); g.lineTo(376, 430); g.moveTo(376, 150); g.lineTo(136, 430); g.stroke();
    typed(g, "FOTOĞRAF YOK", 256, 296, 18, "#222", true, "center");
    const name = st.name || "HALİL", date = st.date || "06.03.2016";
    typed(g, `${name}`, 256, 490, 40, "#111", true, "center");
    typed(g, "Fen İşleri Müdürlüğü gece personeli.", 256, 530, 15, "#111", false, "center");
    typed(g, `En son ${date} gecesi, saat 00:00`, 256, 556, 15, "#111", false, "center");
    typed(g, "köşedeki mazgalın yanında görülmüştür.", 256, 580, 15, "#111", false, "center");
    typed(g, "Üzerinde turuncu yelek ve göğüs kamerası", 256, 614, 15, "#111", false, "center");
    typed(g, "vardır.", 256, 636, 15, "#111", false, "center");
    typed(g, "GÖRENLERİN NÖBET HATTINI ARAMASI RİCA OLUNUR", 256, 690, 13, "#111", true, "center");
    // koparılabilir şeritler
    for (let i = 0; i < 8; i++) { g.strokeStyle = "#777"; g.setLineDash([3, 3]); g.strokeRect(i * 64, 710, 64, 58); g.setLineDash([]); g.save(); g.translate(i * 64 + 36, 760); g.rotate(-Math.PI / 2); typed(g, "NÖBET HATTI", 0, 0, 9, "#111"); g.restore(); }
    g.fillStyle = "#c9c4b0"; g.fillRect(64, 710, 64, 58); g.fillRect(256, 710, 64, 58);         // iki şerit koparılmış
    photocopy(g, w, h, r);
  };

  // P15 SAATLER 512x512: elle çizilmiş 9 saat, hepsi 00:00, biri akrepsiz
  P.p15_saatler = (g, w, h, st = {}) => {
    const r = rng(1515); paper(g, w, h, "#f2eee0", r);
    for (let i = 0; i < 9; i++) {
      const x = 96 + (i % 3) * 160, y = 110 + Math.floor(i / 3) * 150, rad = 58;
      crayon(g, Array.from({ length: 25 }, (_, k) => [x + Math.cos(k / 24 * 6.28) * rad, y + Math.sin(k / 24 * 6.28) * rad]), "#2a2a3a", 3, r);
      for (let k = 0; k < 12; k++) { const a = k / 12 * 6.28; g.fillStyle = "#2a2a3a"; g.fillRect(x + Math.cos(a) * 48 - 1.5, y + Math.sin(a) * 48 - 1.5, 3, 3); }
      if (i !== 7) { crayon(g, [[x, y], [x, y - 44]], "#2a2a3a", 4, r); crayon(g, [[x, y], [x, y - 30]], "#2a2a3a", 7, r); }
      hand(g, i === 7 ? "?" : "00:00", x - 20, y + 82, 14, "#2a2a3a", r);
    }
  };

  // P16 GÖZ MUAYENE LEVHASI 512x768: satırlar küçülür, okununca SELİM / GELMESİN / HALİL
  P.p16_goz = (g, w, h, st = {}) => {
    const r = rng(1616); g.fillStyle = "#f7f7f2"; g.fillRect(0, 0, w, h);
    const lines = [["S", 120], ["E L", 84], ["İ M", 64], ["G E L", 48], ["M E S", 38], ["İ N", 30], ["H A L İ L", 20], ["0 0 : 0 0", 14]];
    let y = 130;
    lines.forEach(([t, s], i) => { typed(g, t, 256, y, s, "#111", true, "center"); typed(g, String(i + 1), 40, y, 12, "#888"); y += s * 0.9 + 30; });
    g.strokeStyle = "#c0201a"; g.lineWidth = 2; g.beginPath(); g.moveTo(80, 612); g.lineTo(432, 612); g.stroke();
    typed(g, "Göz muayenesi · Nöbetçi personel içindir", 256, 735, 12, "#555", false, "center");
  };

  window.OFIS_RESIM = P;
})();
